/** Generate the one-time additive migration; domain comes from the existing config. */
import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import { officialClients, FIRST_PARTY_CERT_SCHEMA } from '../cloudflare-worker/src/first-party.ts';
export function generateFirstPartySql(domain) {
  if (!/^[a-z0-9-]+(?:\.[a-z0-9-]+)+$/.test(domain || '')) throw new Error('Invalid APP_DOMAIN');
  const q = value => "'" + String(value).replaceAll("'", "''") + "'";
  return `-- Migration 14: apply once through Wrangler's migration ledger, after schema 00-13.
-- Generated by tools/generate-first-party-sql.mjs. No signing certificates or APK secrets are seeded.
ALTER TABLE ecosystem_apps ADD COLUMN first_party INTEGER NOT NULL DEFAULT 0;
ALTER TABLE ecosystem_apps ADD COLUMN android_package TEXT;
ALTER TABLE ecosystem_apps ADD COLUMN android_cert_sha256 TEXT NOT NULL DEFAULT '[]';
ALTER TABLE ecosystem_apps ADD COLUMN active INTEGER NOT NULL DEFAULT 1;
ALTER TABLE ecosystem_apps ADD COLUMN allowed_scopes TEXT NOT NULL DEFAULT '[]';
ALTER TABLE oauth_credential_bindings ADD COLUMN bot_verified INTEGER NOT NULL DEFAULT 0;
ALTER TABLE oauth_credential_bindings ADD COLUMN source_session_id TEXT;

${FIRST_PARTY_CERT_SCHEMA.map(sql => sql + ';').join('\n\n')}

${officialClients(domain).map(app => `INSERT INTO ecosystem_apps
  (id, client_id, name, first_party, android_package, redirect_uris, allowed_scopes, is_verified)
VALUES (${q(app.id)}, ${q(app.id)}, ${q(app.name)}, 1, ${q(app.package)}, ${q(JSON.stringify(app.redirects))}, ${q(JSON.stringify(app.scopes))}, 1)
ON CONFLICT(id) DO UPDATE SET first_party = 1, client_id = excluded.client_id, secret_hash = NULL, android_package = excluded.android_package,
  allowed_scopes = excluded.allowed_scopes,
  redirect_uris = (SELECT json_group_array(value) FROM (
    SELECT value FROM json_each(ecosystem_apps.redirect_uris)
    UNION SELECT value FROM json_each(excluded.redirect_uris)));`).join('\n\n')}

CREATE TABLE IF NOT EXISTS auth_schema_versions (version TEXT PRIMARY KEY);
INSERT OR IGNORE INTO auth_schema_versions(version) VALUES ('14_first_party_native');
`;
}
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const config = readFileSync(new URL('../cloudflare-worker/wrangler.toml', import.meta.url), 'utf8');
  process.stdout.write(generateFirstPartySql(process.argv[2] || config.match(/^APP_DOMAIN\s*=\s*"([^"]+)"/m)?.[1]));
}
